function BloomBuddyPage() {
	const search = Route.useSearch();
	const [preferences, setPreferences] = useState({
		language: "en",
		explanationLevel: "beginner",
		answerStyle: "hints_first",
		thinkFirstMode: true,
		activeMaterialId: search.materialId || null
	});
	useEffect(() => {
		if (search.materialId) setPreferences((prev) => ({
			...prev,
			activeMaterialId: search.materialId || null
		}));
	}, [search.materialId]);
	const handlePreferencesChange = (patch) => {
		setPreferences((prev) => ({
			...prev,
			...patch
		}));
	};
	return /* @__PURE__ */ jsx(AppShell, {
		title: "BloomBuddy AI",
		subtitle: "Your supportive study companion. Ask follow-up questions, get hints before full answers, or discuss your uploaded notes.",
		children: /* @__PURE__ */ jsxs("div", {
			className: "grid gap-6 lg:grid-cols-[1fr_20rem]",
			children: [/* @__PURE__ */ jsx(BloomBuddyChat, { preferences }), /* @__PURE__ */ jsx("div", {
				className: "space-y-4",
				children: /* @__PURE__ */ jsx(BloomBuddyControls, {
					preferences,
					onChange: handlePreferencesChange
				})
			})]
		})
	});
}
